import { AxisScale } from '@visx/axis';
import { scaleLinear } from '@visx/scale';
import { isNumber } from 'lodash-es';

import { SparklineYAxisProps } from '../slots/YAxis.js';

const VERTICAL_PADDING = 3;

export const getSparklineYScale = (
  values: number[],
  height: number,
  yAxis: SparklineYAxisProps,
): AxisScale<number> => {
  let minValue: number;
  let maxValue: number;

  if (isNumber(yAxis.min) && isNumber(yAxis.max)) {
    minValue = yAxis.min;
    maxValue = yAxis.max;
  } else {
    minValue = isNumber(yAxis.min) ? yAxis.min : Math.min(...values);
    maxValue = isNumber(yAxis.max) ? yAxis.max : Math.max(...values);
  }

  return scaleLinear({
    domain: [minValue, maxValue],
    range: [height - VERTICAL_PADDING, VERTICAL_PADDING],
  });
};
